const estimate = $('retrieve_estimate').first().json;
const taskTypeData = $('taskypes_ID&Name').first().json;

const rawClientName = "QBE AUSTRALIA PTY LTD." || "";
const jobNumber = "" || "QBEP0035";
const jobDescription = "Premiums 4 Good Trade Stand" || "";
const jobType = "Event" || "";
/**
 * Client Format
 * Example:
 * ABCD0001 -> ABCD | Client Name
 */
const clientPrefix = String(jobNumber).substring(0, 4);

const clientName =
  `${clientPrefix} | ${rawClientName}`;

/**
 * Helpers
 */
const safe = (value, fallback = "") => {
  if (value === null || value === undefined) return fallback;

  return String(value)
    .replace(/&gt;/g, ">")
    .replace(/&lt;/g, "<")
    .replace(/\s+/g, " ")
    .trim();
};

const money = (value) =>
  Number(value || 0).toFixed(2);

/**
 * Dynamic Task Type Mapping
 */
const taskTypeMap = {};

(taskTypeData.id || []).forEach((id, index) => {
  taskTypeMap[id] = {
    name: taskTypeData.name?.[index] || "",
    code: taskTypeData.code?.[index] || ""
  };
});

/**
 * Dynamic Charge Type Mapping
 */
const chargeTypeMap = {
  1: "Time",
  2: "Fixed",
  3: "Cost"
};

const lineItems = [];

for (const entry of estimate.entries || []) {

  const units = Number(entry.units || 0);
  const rate = Number(entry.rate || 0);
  const tax = Number(entry.tax || 0);
  const markUp = Number(entry.markUp || 0);
  const serviceFee = Number(entry.serviceFee || 0);

  const estimateTotal =
    (units * rate) +
    tax +
    markUp +
    serviceFee;

  const mappedTask =
    taskTypeMap[entry.taskTypeId] || {};

  const lineItem = `
Client: ${safe(clientName)}
Product:
Job No.: ${safe(jobNumber)}
Job Description: ${safe(jobDescription)}
Version No.: ${money(estimate.version || 0)}
Title: ${safe(estimate.title)}
Superseded: ${safe(estimate.superseded)}
Date: ${safe(estimate.date)}
Currency Code: A$
Headings Description: ${safe(estimate.title)}
Charge Type: ${
  chargeTypeMap[entry.chargeTypeId] ||
  safe(entry.chargeTypeId)
}
Task Type Code: ${safe(mappedTask.code)}
Description: ${safe(entry.description)}
Units: ${money(units)}
Rate: ${money(rate)}
Mark Ups: ${money(markUp)}
Service Fee: ${money(serviceFee)}
Tax: ${money(tax)}
Estimate Total: ${money(estimateTotal)}
Estimate Notes: ${safe(entry.notes)}
Line Notes:
`
    .replace(/\n/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  lineItems.push(lineItem);
}

const pageContent = lineItems.join(" ").trim();

/**
 * Validation
 */
const errors = [];

if (!jobNumber) {
  errors.push("Missing job number");
}

if (!clientName) {
  errors.push("Missing client name");
}

if (!pageContent) {
  errors.push("Empty page content");
}

if ((estimate.entries || []).length === 0) {
  errors.push("No estimate entries found");
}

/**
 * Stop invalid records
 */
if (errors.length > 0) {

  return [
    {
      json: {
        valid: false,
        errors
      }
    }
  ];
}

/**
 * Valid output
 */
return [
  {
    json: {
      valid: true,
      job_type: jobType,
      job_number: jobNumber,
      client: clientName,
      pageContent
    }
  }
];;

